HAL_Init.exampleCode:
int main(void)
{
  HAL_Init();                       /* 必须最先调用 */
  SystemClock_Config();             /* 配置 72MHz 主频 */
  MX_GPIO_Init();
  while (1) { }
}

HAL_DeInit.exampleCode:
/* 跳转到 bootloader 之前把 HAL 收干净 */
HAL_DeInit();
__disable_irq();
JumpToBootloader();

HAL_MspInit.exampleCode:
void HAL_MspInit(void)
{
  __HAL_RCC_AFIO_CLK_ENABLE();
  __HAL_RCC_PWR_CLK_ENABLE();
  /* 关掉 JTAG 保留 SWD，释放 PA15/PB3/PB4 作普通 IO */
  __HAL_AFIO_REMAP_SWJ_NOJTAG();
}

HAL_IncTick.exampleCode:
/* 自定义节拍源时，在定时器中断里补这一句 */
void TIM6_IRQHandler(void)
{
  HAL_TIM_IRQHandler(&htim6);
  HAL_IncTick();
}

HAL_GetTick.exampleCode:
uint32_t start = HAL_GetTick();
while (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_0) == GPIO_PIN_RESET) {
  if (HAL_GetTick() - start > 500) { /* 超时 500ms */ break; }
}

HAL_Delay.exampleCode:
HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_RESET);
HAL_Delay(500);                       /* 亮 500ms（阻塞） */
HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_SET);
